ALTER PROCEDURE dbo.sp_CatalogProductCategoryCreate @Actor int,@Stamp binary(8),@Code char(5)=NULL,@Name nvarchar(max)=NULL,@ExpectedRevision binary(8)=NULL,@RequestId uniqueidentifier=NULL AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY BEGIN TRANSACTION; EXEC dbo.sp_CatalogDemandActor @Actor,@Stamp;IF @Name IS NULL OR LEN(LTRIM(RTRIM(@Name)))=0 OR LEN(@Name)>50 OR @Name LIKE N'%'+NCHAR(9)+N'%' OR @Name LIKE N'%'+NCHAR(10)+N'%' OR @Name LIKE N'%'+NCHAR(13)+N'%' THROW 51501,'Invalid catalog name.',1; SET @Name=LTRIM(RTRIM(@Name)); IF @RequestId IS NULL THROW 51501,'Request ID required.',1; DECLARE @hash char(64)=CONVERT(char(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),@Name)),2),@old char(5); SELECT @old=EntityCode FROM dbo.CatalogCreateReceipt WITH(UPDLOCK,HOLDLOCK) WHERE RequestId=@RequestId; IF @old IS NOT NULL BEGIN IF NOT EXISTS(SELECT 1 FROM dbo.CatalogCreateReceipt WHERE RequestId=@RequestId AND ActorAccountId=@Actor AND Kind='ProductCategory' AND PayloadHash=@hash) THROW 51508,'Request reused.',1; COMMIT; SELECT MaDM Code,CatalogRevision Revision FROM dbo.DANHMUC_SP WHERE MaDM=@old; RETURN; END; DECLARE @allocated TABLE(Loai varchar(20),Ma char(5)); INSERT @allocated EXEC dbo.sp_CapMa 'DANHMUC_SP'; SELECT @Code=Ma FROM @allocated;INSERT dbo.[DANHMUC_SP]([MaDM],[TenDM]) VALUES(@Code,@Name);INSERT dbo.CatalogCreateReceipt(RequestId,ActorAccountId,Kind,EntityCode,PayloadHash) VALUES(@RequestId,@Actor,'ProductCategory',@Code,@hash);COMMIT; WAITFOR DELAY '00:00:03'; SELECT @Code Code,(SELECT CatalogRevision FROM dbo.[DANHMUC_SP] WHERE [MaDM]=@Code) Revision; END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK; THROW; END CATCH END;